function generic(r, key) {
  const k = `${(key || []).join(' ')} ${r.title || ''}`.toLowerCase();
  const prot = /shrimp|prawn/.test(k) ? 'shrimp' : /lamb|mutton|goat/.test(k) ? 'beef' : /beef|steak|corned/.test(k) ? 'beef' : /pork|ham/.test(k) ? 'pork' : /sausage/.test(k) ? 'sausage' : /chicken|turkey|duck/.test(k) ? 'chicken' : /fish|tuna|cod|salmon/.test(k) ? 'shrimp' : /tofu/.test(k) ? 'tofu' : /egg/.test(k) ? 'scramble' : /bean|lentil|chickpea|pea\b/.test(k) ? 'chickpea' : /potato|taro|yam|cassava/.test(k) ? 'potato' : ['chicken', 'beef', 'chickpea', 'potato'][Math.floor(r() * 4)];
  const veg = ['herb', /tomato/.test(k) ? 'tomato' : 'carrot', /pepper|chili/.test(k) ? 'pepper_red' : 'pea', /spinach|greens|leaves|leaf|kale/.test(k) ? 'spinach' : 'scallion'];
  const sauce = /coconut/.test(k) ? COL.cream : /tomato/.test(k) ? COL.tomato : /curry|turmeric/.test(k) ? COL.curry : /bean|lentil/.test(k) ? COL.bean : /soy/.test(k) ? COL.soy : /cream|milk|cheese/.test(k) ? COL.cream : [COL.brown, COL.butter, COL.green, COL.broth, COL.red_oil, COL.dal][Math.floor(r() * 6)];
  // wrapped in leaves (lu pulu, dolma, tamales in husks…): little green parcels
  if (/leaves|\bleaf\b|wrapped|banana leaf|\bhusk|\bvine\b/.test(k)) {
    const n = 2 + Math.floor(r() * 4), leaf = /husk/.test(k) ? '#E9D18A' : '#4E8A3A', vein = /husk/.test(k) ? '#B89A4E' : '#86C266';
    const filling = /corned|beef/.test(k) ? '#C8705A' : /lamb|mutton|goat/.test(k) ? '#8A5A3A' : /fish|tuna|octopus/.test(k) ? '#F2E6D0' : /pork/.test(k) ? '#E6A58A' : '#D9B26A';
    const base = Math.floor(r() * 3);   // a plate, a banana-leaf platter or a wooden board
    let out = base === 0 ? plate() : base === 1 ? `${shadow(62)}<ellipse cx='0' cy='12' rx='64' ry='16' fill='#3F7F25' ${O}/><path d='M-60 12h120M-40 4l10 8M-10 0l8 12M20 2l6 10M44 6l-6 6' stroke='#86C266' stroke-width='1.4'/>` : `${shadow(62)}<rect x='-62' y='-2' width='124' height='26' rx='8' fill='#B8865A' ${O}/><path d='M-56 6h112M-56 14h112' stroke='#9C6E44' stroke-width='1.2'/>`;
    for (let i = 0; i < n; i++) { const x = -34 + i * (68 / (n - 1 || 1)) + (r() - 0.5) * 6, y = 8 - (i % 2) * 7; out += `<g transform='translate(${x.toFixed(1)} ${y}) rotate(${Math.round(r() * 30 - 15)})'><ellipse rx='15' ry='10' fill='${leaf}' ${O}/><path d='M-12 0h24M-6-6l6 6 6-6' stroke='${vein}' stroke-width='1.4' fill='none'/></g>`; }
    // one is cut open so you can see what's inside
    out += `<g transform='translate(${(r() * 30 - 15).toFixed(1)} 14)'><ellipse rx='13' ry='8' fill='${leaf}' ${O}/><ellipse rx='9' ry='5' fill='${filling}' ${o}/>${/coconut/.test(k) ? `<ellipse cx='2' cy='-1' rx='4' ry='2' fill='#FFFFFF' opacity='.85'/>` : ''}</g>`;
    const side = Math.floor(r() * 3);
    if (side === 0) out += rice(r, 44, 20, 12, 10);
    if (side === 1) out += `<g transform='translate(46 16)'><path d='M-8 0a8 8 0 0 1 16 0z' fill='#9CCB5A' ${O}/><path d='M-5 -1l5-5 5 5' stroke='#E9F5C9' stroke-width='1.2' fill='none'/></g>`;
    if (side === 2) out += `<ellipse cx='-44' cy='18' rx='12' ry='5' fill='#FFFFFF' ${o}/>`;
    return out;
  }
  const soupy = /soup|stew|broth|curry|chowder|\bwat\b|\bpot\b/.test(k);
  const style = soupy ? 0 : 1 + Math.floor(r() * 3);
  if (style === 0) { const b = bowl(['#FFFFFF', '#F2E6C8', '#2F4058'][Math.floor(r() * 3)], ['#2F6DB5', '#C8352F', '#3F7F25'][Math.floor(r() * 3)]); return b.back + fill(b.area, sauce) + scatter(r, [prot, ...veg.slice(0, 2)], 9, b.area, 1.1) + (b.front || ''); }
  if (style === 1) { const a = { cx: 10, cy: 4, rx: 26, ry: 7 }; return plate() + rice(r, -28, 12, 18, 14, /potato|taro/.test(k) ? '#FBF0D2' : '#FFFFFF') + scatter(r, prot, 7, a, 1.4) + scatter(r, veg, 8, a, 1); }
  if (style === 2) { const v = skillet(); return v.back + fill(v.area, sauce) + scatter(r, [prot, prot, ...veg], 11, v.area, 1.15); }
  if (style === 3) { const v = cazuela(); return v.back + fill(v.area, sauce) + scatter(r, [prot, veg[1], veg[0]], 10, v.area, 1.1) + drizzle(v.area, '#FFFFFF', 1.6); }
  return plate() + skewer(-4, 0, [sauce, '#7BAA4A', sauce, '#D9472B', sauce].map((c) => (c === COL.cream ? '#E9C98A' : c))) + scatter(r, veg, 6, { cx: 0, cy: 12, rx: 40, ry: 7 }, 0.9);
}
// no title match: if the main ingredient makes it obvious (a fish dish, a chicken dish), draw that
function keyFamily(r, key) {
  const k = (key || []).join(' ').toLowerCase(); const pick = (re) => FAMILIES.find(([x]) => x.test(re));
  const f = /\b(fish|salmon|tuna|cod|tilapia|snapper)\b/.test(k) ? pick('fish') : /\bcrab|lobster\b/.test(k) ? pick('crab') : /\b(chicken|turkey|duck)\b/.test(k) ? pick('chicken') : null;
  return f ? f[1](r) : '';
}
const DRUM = (x, y) => `<g transform='translate(${x} ${y}) rotate(-20)'><path d='M6 0h10' stroke='${INK}' stroke-width='6' stroke-linecap='round'/><path d='M6 0h10' stroke='#F7EEDC' stroke-width='3' stroke-linecap='round'/><ellipse cx='-2' cy='0' rx='10' ry='7' fill='#C9772E' ${o}/></g>`;

export function dishArt({ title, key } = {}) {
  const t = String(title || '').toLowerCase();
  const r = rng(t); r.title = t;
  const m = (/jollof|biryani|pilaf|pilau|plov|pulao|machboos|kabsa|mandi|thieboudienne|bibimbap/.test(t) && FAMILIES.find(([re]) => re.test(t))) || MAKERS.find(([re]) => re.test(t)) || FAMILIES.find(([re]) => re.test(t));
  let svg = m ? m[1](r) : keyFamily(r, key) || generic(r, key);
  if (/arroz con pollo/.test(t)) svg += DRUM(-14, -2) + DRUM(16, 2);
  return svg;
}
